"""Stock Market, chapter 2: "Think like an investor". Rupees, assumed rates, no promises of returns.
Figures are checked in tests/check_more_chapters.py. Educational, not financial advice."""
from seed_data import _id, _intro, _teach, _example, _flash, _mcq, _concept
from seed_finance import _choice, _outcome
from seed_money_more import _chat, _swipe, _slider, _match

CHAPTER_KEY = "think-like-an-investor"


def build_stock_chapter_two(course_id):
    ch_id = _id()
    ch = {"id": ch_id, "course_id": course_id, "order": 2, "key": CHAPTER_KEY,
          "title": "Think like an investor",
          "description": "Stay calm when markets fall, keep costs low, understand mutual funds and match money to goals."}
    m_id = _id()
    m = {"id": m_id, "chapter_id": ch_id, "order": 1, "title": "Habits that last"}

    # ---------------------------------------------------------------- 1. falls
    c1 = _concept(m_id, 1,
        "When the market falls",
        "Understand why falls happen, what recovery needs, and why panic selling hurts.",
        "Markets go down as well as up, sometimes sharply. A fall only becomes a real loss if you sell at the bottom. "
        "Knowing the maths of falls and recoveries makes it easier to stay calm and keep your plan.",
        "Ishaan's ₹1,00,000 investment drops 30% to ₹70,000. To get back to ₹1,00,000 it now needs to rise about 42.9%, not 30%. "
        "That is why long-term investors keep money they will not need soon, and why they avoid selling in a panic.",
        ["Markets rise and fall. Falls are normal, not a sign something is broken.",
         "A 30% fall needs about a 43% rise to recover, and a 50% fall needs 100%.",
         "A SIP buys more units when prices are low, which helps over time.",
         "Only invest money you will not need for several years in shares."],
        ["Selling in a panic after a big fall.",
         "Stopping a SIP just when units are cheapest.",
         "Putting money you need soon into the market."],
        [
            _intro("The red day", "Ishaan opens his investment app and everything is red. His ₹1,00,000 has become ₹80,000 in a month. His heart is racing. What should he do?"),
            _chat("Ishaan panics", "A chat during a market fall", [
                ("friend", "Ishaan", "Lumi, my investment is down 20%! Should I sell everything?"),
                ("lumi", "Lumi", "Take a breath. Is this money for something you need in the next year or two?"),
                ("friend", "Ishaan", "No, it's for 10 years from now."),
                ("lumi", "Lumi", "Then a fall is uncomfortable but not a disaster. You only lose for real if you sell low."),
                ("friend", "Ishaan", "But what if it keeps falling?"),
                ("lumi", "Lumi", "It might. In March 2020 India's Nifty 50 fell roughly 38% in about two months. It was back above its old high within the same year. No one can promise that will repeat."),
                ("friend", "Ishaan", "And my monthly SIP?"),
                ("lumi", "Lumi", "Keep it going. Lower prices mean each rupee buys more units."),
            ], "A fall is a loss on paper until you sell. Money you need soon should not be in shares."),
            _teach("Why falls hurt more than they look",
                   "Say ₹100 falls 50% to ₹50. To get back to ₹100, it must rise 100%, because the gain is calculated on a smaller amount. A 30% fall needs about a 43% rise. This is why big falls are painful and why people prefer investments that do not swing wildly when they need money soon.",
                   ["A 10% fall needs about 11% to recover", "A 30% fall needs about 43%", "A 50% fall needs 100%", "Bigger falls need much bigger recoveries"]),
            _slider("How big a recovery do you need?", "Drag the fall and see what it takes to get back to where you started.", "drawdown",
                    [("amount", "Amount invested", 10000, 500000, 10000, 100000, "₹", ""), ("loss", "Market fall", 5, 70, 5, 30, "", "%")],
                    "The deeper the fall, the steeper the climb back. Keep short-term money out of shares."),
            _example("The SIP that kept buying",
                     "Aarav invests ₹5,000 a month. The price per unit goes 50, 40, 25, 40, 50. He buys 100, 125, 200, 125 and 100 units, 650 in all for ₹25,000, an average cost of about ₹38.46 per unit. When the price is back at 50, his 650 units are worth ₹32,500 even though the price just returned to where it started.",
                     "A SIP automatically buys more when prices are low. Stopping it during a fall means missing those cheaper units."),
            _swipe("Market falls: myth or fact?", [
                ("Selling after a fall turns a paper loss into a real loss.", "fact", "Until you sell, the loss is only on paper. Selling makes it permanent, and you may miss the recovery."),
                ("Markets have never recovered from a fall.", "myth", "Broad markets have recovered from past falls over time, though it can take months or years and nothing is guaranteed."),
                ("A SIP buys more units when prices are low.", "fact", "A fixed amount buys more units at a lower price. That is called rupee-cost averaging."),
                ("You should pause your SIP whenever the market drops.", "myth", "Pausing means skipping the cheapest units. Stopping because of fear is a common mistake."),
                ("Money you need next year belongs in shares.", "myth", "Short-term money should not depend on the market. A fall could force you to sell at a loss."),
            ]),
            _choice("Ishaan's ₹1,00,000, meant for 10 years from now, has fallen 20% to ₹80,000. A friend says to sell before it drops more.",
                    "What is the most sensible response?",
                    [("Sell everything now to stop the loss", "bad",
                      "Selling after a fall locks in the loss and means he must also guess when to get back in. Many people sell low and buy high this way.",
                      _outcome(("Value after the fall", 80000), ("Gain needed to recover", 25), "From ₹80,000 he needs a 25% rise to get back to ₹1,00,000.")),
                     ("Stay with the plan, keep the SIP going, and check that the goal is still 10 years away", "good",
                      "Right. The goal is far away, so a fall is uncomfortable but not a reason to change the plan. No outcome is guaranteed, but panic selling is the surest way to lock in a loss."),
                     ("Pour in all his savings now to 'buy the dip'", "ok",
                      "Buying more at lower prices can work, but putting in money he needs elsewhere is risky. Nobody knows where the bottom is.")]),
            _choice("Sana will need ₹2,00,000 for a course fee in 8 months. Her money is in a share fund that just fell 15%.",
                    "What does this teach her?",
                    [("Money needed soon should not sit in shares, because a fall can hit just when you need it", "good",
                      "Yes. With only 8 months, there is no time to recover. Short-term goals suit safer places such as a bank deposit or a liquid option.",
                      _outcome(("Planned fee", 200000), ("Fund value after 15% fall", 170000), "She would be ₹30,000 short at the worst time.")),
                     ("She should buy more shares to catch up", "bad", "More risk with less time makes a shortfall more likely, not less."),
                     ("Nothing, because shares always rise within a year", "bad", "No investment is guaranteed to rise in any fixed time. That belief is how short-term money gets hurt.")]),
            _mcq("A ₹1,00,000 investment falls 50%. About how much must it rise to get back to ₹1,00,000?", ["50%", "75%", "100%", "150%"], 2,
                 "From ₹50,000 it must double, which is a 100% rise. Recoveries are calculated on the smaller amount."),
            _mcq("What does a SIP do when prices fall?", ["Buys fewer units", "Buys more units for the same amount", "Stops automatically", "Sells your units"], 1,
                 "A fixed monthly amount buys more units when the price is lower, which can lower your average cost."),
            _flash("Falls, in one line", "A fall is only a real loss if you sell. Keep short-term money out of shares."),
        ], xp=30)

    # ---------------------------------------------------------------- 2. costs
    c2 = _concept(m_id, 2,
        "Costs that eat returns",
        "See how small yearly fees compound into big differences, and choose low-cost options.",
        "Every mutual fund charges a yearly fee called the expense ratio. A difference of 1% a year sounds tiny but compounds "
        "over the years into lakhs of rupees you never see leaving.",
        "Aarav invests ₹5,000 a month for 20 years at an assumed 12% before costs. With a low-cost plan (0.2% fee) he ends with about ₹48.6 lakh. "
        "With a costly plan (1.5% fee) he ends with about ₹40.9 lakh. The fee difference costs him about ₹7.7 lakh.",
        ["The expense ratio is a yearly fee taken from your fund.",
         "Direct plans usually cost less than regular plans because there is no distributor commission.",
         "A 1% fee difference can cost lakhs over 20 years.",
         "Past returns do not promise future returns, so do not chase last year's winner."],
        ["Ignoring fees because they look like small percentages.",
         "Buying a regular plan without knowing a direct plan exists.",
         "Switching funds often and paying costs each time."],
        [
            _intro("The fee you never see", "Nobody sends you a bill for your fund's fee. It is taken quietly from the fund's value every day. That is why it is easy to ignore, and why it matters so much."),
            _chat("Direct or regular?", "Aarav asks Lumi about his friend's advice", [
                ("friend", "Aarav", "My bank's agent says I should buy this fund through him. He says it is the same fund."),
                ("lumi", "Lumi", "It might be the same fund, but through an agent it is usually a 'regular plan', which pays him a commission built into the fee."),
                ("friend", "Aarav", "And a direct plan?"),
                ("lumi", "Lumi", "You buy it straight from the fund house or an app, with no commission, so the yearly fee is lower."),
                ("friend", "Aarav", "How much lower can that be?"),
                ("lumi", "Lumi", "Often around 0.5 to 1 percentage point a year, depending on the fund. Over 20 years that adds up to lakhs."),
                ("friend", "Aarav", "Okay, I will look at direct plans. Does the agent do anything for his fee?"),
                ("lumi", "Lumi", "Some give useful guidance. Just know what you are paying for."),
            ], "Costs come off your returns every year. Know what you pay and what you get for it."),
            _teach("The expense ratio",
                   "The expense ratio is the percentage of your money a fund charges every year to run itself. It is already taken out of the fund's returns, so you never see a separate bill. Index funds, which simply copy a market index, often have very low fees, sometimes around 0.1 to 0.5%. Actively managed funds often charge more. A higher fee needs the fund manager to do better just to break even with a cheaper option.",
                   ["Charged every year, taken from the fund", "Direct plans usually cost less than regular plans", "Index funds often have low fees", "Check the expense ratio before you buy"]),
            _slider("What does the fee cost you?", "Move the sliders. Compare a low-cost plan with a costlier one, on the same monthly amount.", "cost",
                    [("monthly", "Invest every month", 1000, 25000, 500, 5000, "₹", ""), ("years", "For how many years", 5, 40, 1, 20, "", " yrs"), ("rate", "Assumed return before costs", 6, 15, 1, 12, "", "%"), ("cost", "Costlier plan's yearly fee", 0.5, 2.5, 0.1, 1.5, "", "%")],
                    "Fees compound just like returns, in the wrong direction. Check them before you buy, not after."),
            _example("Same fund, different plans",
                     "Two friends invest ₹5,000 a month for 20 years, ₹12 lakh in total, in funds that earn the same 12% before costs. One pays 0.2% a year and ends with about ₹48.6 lakh. The other pays 1.5% and ends with about ₹40.9 lakh. Same effort, same market, ₹7.7 lakh less.",
                     "The cheaper plan did nothing extra. It simply kept more of the return for its owner."),
            _swipe("Fees and funds: myth or fact?", [
                ("A direct plan and a regular plan of the same fund hold the same investments.", "fact", "They own the same shares. The difference is the commission, which makes the regular plan's yearly fee higher."),
                ("A 1% yearly fee is too small to matter.", "myth", "Over 20 years a 1% difference compounds into a very large sum, as the slider showed."),
                ("Last year's best fund will be next year's best.", "myth", "Top funds change often. Past returns do not promise future returns."),
                ("Switching funds often is free.", "myth", "Switching can mean exit loads, taxes and missing gains. Frequent trading usually costs more than it earns."),
            ]),
            _choice("An agent offers Aarav a 'special' fund with a 2% yearly fee and says it beat the market last year.",
                    "What is the smartest thing to check?",
                    [("Whether the extra fee has a good reason, and how a low-cost direct or index option compares", "good",
                      "Right. One good year proves little, and a high fee is a hurdle every single year. Compare the same kind of fund at a lower cost before deciding.",
                      _outcome(("2% fee plan after 20 years", 3828485), ("0.2% fee plan after 20 years", 4862379), "With the same 12% before costs, the high fee leaves about ₹10.3 lakh less.")),
                     ("Buy it, because last year's winner will probably win again", "bad", "Past winners often fall back. Chasing them while paying a high fee is a common way to lose out."),
                     ("Ignore all fees and pick the one with the best-looking return", "bad", "Returns shown may already include the fee, and they are in the past. Understand the fee and the risk, not just the headline number.")]),
            _choice("Priya's fund was 3rd best last year. A friend says to switch to this year's top fund, which has a 1.8% fee.",
                    "What is wrong with switching every year to the latest winner?",
                    [("It adds costs and taxes and chases the past, which does not predict the future", "good",
                      "Yes. Each switch can cost exit loads and tax, and the new winner is often not next year's winner.",
                      _outcome(("Fee on current plan", 0.3), ("Fee on 'top fund'", 1.8), "She would pay six times the fee for a track record that may not repeat.")),
                     ("Nothing, it is a smart habit", "bad", "Chasing recent winners is one of the best-known ways to underperform."),
                     ("Only the tax matters", "ok", "Tax matters, but so do fees and the fact that past returns do not predict the future.")]),
            _mcq("What does a lower expense ratio mean for you?", ["More of the fund's return stays with you", "The fund is risk-free", "Guaranteed higher returns", "A shorter lock-in"], 0,
                 "A lower fee leaves more of the return in your pocket. It does not remove risk or guarantee returns."),
            _mcq("Why are direct plans usually cheaper than regular plans?", ["They hold safer shares", "They skip the distributor's commission", "They are run by the government", "They invest less"], 1,
                 "A regular plan includes a commission for the distributor. A direct plan does not."),
            _flash("Costs, in one line", "A small yearly fee compounds into a large loss over decades. Pick low cost where you can."),
        ], xp=30)

    # ---------------------------------------------------------------- 3. mutual funds
    c3 = _concept(m_id, 3,
        "Mutual funds in plain words",
        "Know what a mutual fund is, the main types, and how to read the basics before buying.",
        "A mutual fund pools money from many people and invests it in shares, bonds or both. You own units of the fund. "
        "Different types carry different risks, and a few simple labels help you understand what you are buying.",
        "Arjun puts ₹5,000 a month into an index fund that copies the Nifty 50. He owns units, not shares directly. "
        "The fund buys the 50 companies for him, and the riskometer on the fund tells him it has a high level of risk.",
        ["A mutual fund pools many investors' money and invests it for them.",
         "NAV is the price of one unit. A low NAV does not mean a cheap fund.",
         "Equity funds can swing a lot, debt funds are usually steadier, and hybrid funds mix both.",
         "Check the riskometer, the expense ratio and any exit load before you buy."],
        ["Choosing a fund because its NAV is low.",
         "Not reading the riskometer.",
         "Buying an ELSS without knowing it locks your money for three years."],
        [
            _intro("A basket of businesses", "You cannot easily buy 50 companies on your own with ₹500. A mutual fund lets you and thousands of others chip in and own a slice of a whole basket."),
            _chat("What is a unit?", "Arjun asks Lumi", [
                ("friend", "Arjun", "I bought a fund with a NAV of ₹15. My friend's is ₹800. Mine must be way cheaper, right?"),
                ("lumi", "Lumi", "Good question, but no. NAV is just the price of one unit, like the price of one slice."),
                ("friend", "Arjun", "So a small slice is not a better deal?"),
                ("lumi", "Lumi", "Right. If both funds grow 10%, both investors gain 10%. The slice size does not matter, the growth does."),
                ("friend", "Arjun", "What should I look at instead?"),
                ("lumi", "Lumi", "The type of fund, the risk level, the fee, and how long you can stay invested."),
            ], "A low NAV is not a bargain. Look at type, risk, cost and time."),
            _match("Match the fund type to what it does", [
                ("Equity fund", "Invests mainly in shares; can swing a lot"),
                ("Debt fund", "Invests in bonds; usually steadier but not risk-free"),
                ("Hybrid fund", "Mixes shares and bonds"),
                ("Index fund", "Copies a market index like the Nifty 50"),
            ]),
            _teach("Three labels to check",
                   "First, the type: equity, debt, hybrid or index, which tells you how much it can swing. Second, the riskometer, a SEBI label from low to very high risk. Third, the costs: the yearly expense ratio and any exit load, a fee for leaving too early, which many equity funds charge within the first year. An ELSS is an equity fund with a three-year lock-in that can qualify for tax deduction under the old tax regime.",
                   ["Type tells you how much it can swing", "Riskometer: low to very high", "Expense ratio and exit load are costs", "ELSS locks money for 3 years"]),
            _example("Large, mid and small",
                     "Funds often invest in companies of different sizes. Large-cap funds hold the 100 biggest listed companies, mid-caps the next 150, and small-caps the rest. Smaller companies can grow faster but can also fall harder, so a small-cap fund usually swings more than a large-cap fund.",
                     "Size changes risk. Bigger and older companies are generally steadier, and smaller ones are generally more volatile."),
            _swipe("Mutual funds: myth or fact?", [
                ("A fund with a low NAV is cheaper than one with a high NAV.", "myth", "NAV is just the price of one unit. What matters is the percentage growth, not the unit price."),
                ("A mutual fund spreads your money across many investments.", "fact", "That is diversification, one of the main benefits of a fund."),
                ("Mutual fund returns are guaranteed.", "myth", "Mutual funds are subject to market risk. Returns are not guaranteed."),
                ("The riskometer helps you see how risky a fund is.", "fact", "It is a simple label from low to very high risk. Read it before you buy."),
            ]),
            _choice("Rhea, 20, wants to start with ₹1,000 a month and does not want to pick stocks. A friend suggests a low-cost index fund. Another suggests a tiny company's share because it 'only costs ₹12'.",
                    "What is wrong with choosing by the low price?",
                    [("A low price per unit or share says nothing about value or growth. Cost, risk and diversification matter more", "good",
                      "Yes. A ₹12 share can fall to ₹6 as easily as a ₹1,200 share can. An index fund spreads her money across many companies. This is education, not advice.",
                      _outcome(("₹12 share after a 50% fall", 6), ("Gain needed to recover", 100), "A cheap share can lose half its value and then need to double to recover.")),
                     ("Nothing, cheaper is always better", "bad", "Price per share is not the same as value. A cheap-looking share can still be a bad deal."),
                     ("She should wait until she can afford an expensive share", "ok", "She does not need to wait. A SIP lets her start small, and funds avoid the need to pick single shares.")]),
            _choice("Nikhil needs ₹50,000 in 4 months for a laptop. A fund-seller recommends a small-cap equity fund because it 'gave 30% last year'.",
                    "What should Nikhil think about first?",
                    [("His timeline is 4 months, which is too short for a fund that can swing a lot", "good",
                      "Right. Small-cap funds can fall sharply over a few months, and one great year does not promise the next. Short goals suit safer options.",
                      _outcome(("Planned laptop money", 50000), ("If the fund falls 20%", 40000), "A 20% dip would leave him ₹10,000 short just when he needs the money.")),
                     ("Buy it, because 30% is a great return", "bad", "Past returns do not promise future returns, and he has no time to recover from a fall."),
                     ("Put in extra money so the fall does not matter", "bad", "Adding more money to a risky, short-term bet just raises how much can be lost.")]),
            _mcq("What does NAV stand for, and what does it show?", ["Net Asset Value, the price of one unit", "New Annual Value, the yearly return", "Net Average Volume, the number of units", "National Asset Value, the fund's rank"], 0,
                 "Net Asset Value is the price of one unit of the fund. It tells you nothing about whether the fund is cheap."),
            _mcq("What is an ELSS fund?", ["A bank deposit", "An equity fund with a 3-year lock-in that can qualify for tax deduction under the old regime", "A government bond", "A fund with no risk"], 1,
                 "ELSS stands for Equity Linked Savings Scheme. It invests in shares and locks your money for three years."),
            _flash("A mutual fund, in one line", "A pooled basket of investments you own units of. Check its type, risk and cost."),
        ], xp=30)

    # ---------------------------------------------------------------- 4. goals
    c4 = _concept(m_id, 4,
        "Match your money to your goals",
        "Choose where money should sit based on when you will need it.",
        "Money has a deadline. Money you need in a year should sit somewhere steady. Money for 10 years or more can ride out the swings of shares. "
        "Matching the place to the time is the single most useful investing habit.",
        "Kavya sorts her money into three jobs: her laptop in 6 months, a trip in 3 years and her future in 25 years. Each goes into a different place, matched to its deadline.",
        ["Match the investment to when you need the money.",
         "Under 3 years: steadier places such as bank deposits.",
         "5 to 10 years or more: shares can make sense because there is time to ride out falls.",
         "Write each goal and its date down so the plan is clear."],
        ["Putting every goal into the same investment.",
         "Taking short-term money into shares for 'higher returns'.",
         "Keeping long-term money in a savings account out of fear."],
        [
            _intro("Every rupee has a deadline", "Some money is for next month. Some is for 20 years from now. Treating them the same is how people get hurt."),
            _chat("Three goals", "Kavya makes a plan with Lumi", [
                ("friend", "Kavya", "I want a laptop in 6 months, a Goa trip in 3 years, and to save for later in life. Can I put it all in one fund?"),
                ("lumi", "Lumi", "Let's look at each goal's deadline. The laptop is 6 months away. Could a market fall hurt you?"),
                ("friend", "Kavya", "Yes, I would need the money right then."),
                ("lumi", "Lumi", "So that goes somewhere steady. The Goa trip in 3 years can take a bit more risk, but not too much."),
                ("friend", "Kavya", "And the one for later?"),
                ("lumi", "Lumi", "With 25 years, short-term falls matter much less, so shares can play a bigger part."),
                ("friend", "Kavya", "So the deadline decides the place."),
            ], "The deadline decides where the money should sit."),
            _match("Match the goal to a sensible kind of place", [
                ("Laptop in 6 months", "Steady and easy to access, like a bank deposit"),
                ("Trip in 3 years", "A mix of steady and moderate-risk options"),
                ("Wealth in 25 years", "Mostly shares, such as index funds, and time"),
                ("Emergency fund", "Cash you can reach at once"),
            ]),
            _teach("Time decides risk",
                   "The longer you can leave money alone, the more falls you can sit through, so the more shares make sense. The shorter the time, the less you can risk. A rough guide many people use: under 3 years, keep money steady; 3 to 5 years, a careful mix; over 7 to 10 years, shares can play a larger role. These are guides to learn from, not advice for your situation.",
                   ["Under 3 years: steady places", "3 to 5 years: a careful mix", "7 to 10 years or more: shares can fit", "Review as the goal gets closer"]),
            _example("Moving to safety as the date nears",
                     "Meera is saving for a house deposit in 10 years. In the early years she keeps most of it in an equity fund. As the date gets closer she shifts part of it into steadier places, so a fall in the final year cannot ruin the plan.",
                     "As a goal approaches, the money gets safer. That protects what you have built."),
            _swipe("Goals and time: myth or fact?", [
                ("Money needed in a year should be in shares for higher returns.", "myth", "A fall in that one year could leave a hole you cannot refill in time."),
                ("Long-term money can often take more risk than short-term money.", "fact", "More time means more room to ride out falls, though nothing is guaranteed."),
                ("One investment should hold all your goals.", "myth", "Different goals have different deadlines and need different places."),
                ("You should keep long-term money in a savings account out of fear.", "myth", "Over decades, inflation can quietly beat a plain savings account. Fear can be costly too."),
            ]),
            _choice("Zoya needs ₹1,50,000 for her sister's wedding gift in 10 months. She has the money in an equity fund after 2 great years.",
                    "What should she think about?",
                    [("Move it to a steady place, because 10 months is too short to risk a fall", "good",
                      "Right. Even after great years, a drop right before the date could hurt. Steadier options protect a short-term goal.",
                      _outcome(("Goal", 150000), ("If shares fall 20%", 120000), "A 20% fall would leave her ₹30,000 short.")),
                     ("Keep going because shares did great for 2 years", "bad", "Past performance does not predict the next 10 months."),
                     ("Put even more in to cover possible falls", "bad", "More money in the risky place makes the shortfall bigger if it falls.")]),
            _choice("Dhruv, 21, has money for retirement that he will not touch for 35 years. He keeps it all in a savings account because 'shares are scary'.",
                    "What should he consider?",
                    [("Over 35 years, inflation can eat a plain savings account, so a long-term mix with shares may fit", "good",
                      "Right. With decades ahead, short-term falls matter less, and inflation matters more. Learn it, start small, and match the risk to his comfort.",
                      _outcome(("₹1,00,000 at 4% for 30 years", 324340), ("₹1,00,000 at 10% for 30 years", 1744940), "These are illustrations at assumed rates, not promises. Over long periods the gap is large.")),
                     ("Nothing is wrong, since a savings account is safest", "ok", "Safe from falling, yes, but with decades to go it can lose to inflation. That is a different risk."),
                     ("Put everything into one risky share", "bad", "More risk is not the answer. Spreading across many shares and staying invested is the lesson.")]),
            _mcq("Which goal is most suited to staying in shares?", ["A fee due in 6 months", "A holiday in 1 year", "Retirement 30 years away", "Rent due next month"], 2,
                 "A long horizon gives time to recover from falls. Short-term goals cannot afford a fall."),
            _mcq("Why shift money to safer places as a goal gets closer?", ["To earn more", "To protect what you have built from a late fall", "Because shares stop working", "Because taxes rise"], 1,
                 "Moving to steadier places near the date protects your savings from a fall right before you need them."),
            _flash("Goals, in one line", "Match where money sits to when you need it."),
        ], xp=30)

    m["concepts"] = [c1, c2, c3, c4]
    ch["modules"] = [m]
    return ch
